import{_ as t,o as e,c as r,a2 as l}from"./chunks/framework.xlC3Vtar.js";const p=JSON.parse('{"title":"快速开始","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started.md","filePath":"guide/getting-started.md"}'),i={name:"guide/getting-started.md"};function o(d,a,h,n,s,c){return e(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>欢迎使用 SnipX！本指南将帮助你快速上手。</p><h2 id="📥-安装" tabindex="-1">📥 安装 <a class="header-anchor" href="#📥-安装" aria-label="Permalink to &quot;📥 安装&quot;">​</a></h2><h3 id="下载-snipx" tabindex="-1">下载 SnipX <a class="header-anchor" href="#下载-snipx" aria-label="Permalink to &quot;下载 SnipX&quot;">​</a></h3><p>访问 <a href="/SnipX/download.html">下载页面</a> 下载最新版本。</p><p>推荐下载 <strong>单文件版本</strong>（SnipX.exe），无需安装，解压即用。</p><h3 id="运行程序" tabindex="-1">运行程序 <a class="header-anchor" href="#运行程序" aria-label="Permalink to &quot;运行程序&quot;">​</a></h3><p>双击 <code>SnipX.exe</code> 运行程序。</p><p>首次运行时，程序会：</p><ol><li>创建配置文件</li><li>注册全局热键</li><li>显示托盘图标（可选）</li></ol><hr><h2 id="🎯-第一次截图" tabindex="-1">🎯 第一次截图 <a class="header-anchor" href="#🎯-第一次截图" aria-label="Permalink to &quot;🎯 第一次截图&quot;">​</a></h2><h3 id="启动截图" tabindex="-1">启动截图 <a class="header-anchor" href="#启动截图" aria-label="Permalink to &quot;启动截图&quot;">​</a></h3><p>按 <code>Alt+X</code> 启动区域截图，或按 <code>Alt+F</code> 进行全屏截图。</p><p>屏幕会变暗，进入截图模式。</p><h3 id="选择区域" tabindex="-1">选择区域 <a class="header-anchor" href="#选择区域" aria-label="Permalink to &quot;选择区域&quot;">​</a></h3><p><strong>方法 1：拖拽选择</strong></p><ol><li>按住鼠标左键</li><li>拖拽选择区域</li><li>松开鼠标</li></ol><p><strong>方法 2：窗口检测</strong></p><ol><li>移动鼠标到窗口上</li><li>窗口会自动高亮</li><li>点击鼠标左键选择该窗口</li></ol><p><strong>方法 3：全屏截图</strong></p><ol><li>按 <code>Alt+F</code> 进行全屏截图</li></ol><h3 id="调整选区" tabindex="-1">调整选区 <a class="header-anchor" href="#调整选区" aria-label="Permalink to &quot;调整选区&quot;">​</a></h3><p>选择区域后，可以：</p><ul><li><strong>移动选区</strong>：拖拽选区内部</li><li><strong>调整大小</strong>：拖拽选区边缘或角落</li><li><strong>微调</strong>：使用方向键（1px）或 <code>Shift+方向键</code>（10px）</li></ul><h3 id="确认选区" tabindex="-1">确认选区 <a class="header-anchor" href="#确认选区" aria-label="Permalink to &quot;确认选区&quot;">​</a></h3><ul><li>按 <code>Enter</code> 确认选区</li><li>或双击选区内部</li></ul><hr><h2 id="🎨-添加标注" tabindex="-1">🎨 添加标注 <a class="header-anchor" href="#🎨-添加标注" aria-label="Permalink to &quot;🎨 添加标注&quot;">​</a></h2><p>确认选区后，会显示工具栏。</p><h3 id="选择工具" tabindex="-1">选择工具 <a class="header-anchor" href="#选择工具" aria-label="Permalink to &quot;选择工具&quot;">​</a></h3><p>点击工具栏上的工具按钮：</p><ul><li>🔲 矩形</li><li>⭕ 椭圆</li><li>➡️ 箭头</li><li>✏️ 铅笔</li><li>📝 文字</li><li>📏 直线</li><li>① 序号</li><li>🟨 高亮</li><li>🔳 马赛克</li><li>🌫️ 模糊</li></ul><h3 id="绘制标注" tabindex="-1">绘制标注 <a class="header-anchor" href="#绘制标注" aria-label="Permalink to &quot;绘制标注&quot;">​</a></h3><p>选择工具后：</p><ol><li><strong>矩形/椭圆/箭头/直线/高亮</strong>：拖拽绘制</li><li><strong>铅笔</strong>：按住鼠标左键自由绘制</li><li><strong>文字</strong>：点击位置，输入文字</li><li><strong>马赛克/模糊</strong>：拖拽涂抹</li><li><strong>序号</strong>：点击添加</li></ol><h3 id="调整颜色和粗细" tabindex="-1">调整颜色和粗细 <a class="header-anchor" href="#调整颜色和粗细" aria-label="Permalink to &quot;调整颜色和粗细&quot;">​</a></h3><ul><li><strong>颜色</strong>：点击工具栏上的颜色块，选择颜色</li><li><strong>粗细</strong>：点击工具栏上的粗细区域，循环切换</li></ul><hr><h2 id="💾-保存截图" tabindex="-1">💾 保存截图 <a class="header-anchor" href="#💾-保存截图" aria-label="Permalink to &quot;💾 保存截图&quot;">​</a></h2><h3 id="保存到文件" tabindex="-1">保存到文件 <a class="header-anchor" href="#保存到文件" aria-label="Permalink to &quot;保存到文件&quot;">​</a></h3><p>按 <code>Ctrl+S</code> 打开保存对话框：</p><ol><li>选择保存位置</li><li>输入文件名</li><li>选择格式（PNG/JPG/BMP）</li><li>点击&quot;保存&quot;</li></ol><h3 id="复制到剪贴板" tabindex="-1">复制到剪贴板 <a class="header-anchor" href="#复制到剪贴板" aria-label="Permalink to &quot;复制到剪贴板&quot;">​</a></h3><p>按 <code>Ctrl+C</code> 复制到剪贴板，然后可以粘贴到其他应用。</p><h3 id="快速复制" tabindex="-1">快速复制 <a class="header-anchor" href="#快速复制" aria-label="Permalink to &quot;快速复制&quot;">​</a></h3><p>双击选区快速复制并退出。</p><hr><h2 id="⌨️-常用快捷键" tabindex="-1">⌨️ 常用快捷键 <a class="header-anchor" href="#⌨️-常用快捷键" aria-label="Permalink to &quot;⌨️ 常用快捷键&quot;">​</a></h2><h3 id="截图相关" tabindex="-1">截图相关 <a class="header-anchor" href="#截图相关" aria-label="Permalink to &quot;截图相关&quot;">​</a></h3><table tabindex="0"><thead><tr><th>快捷键</th><th>功能</th></tr></thead><tbody><tr><td><code>Alt+X</code></td><td>启动区域截图</td></tr><tr><td><code>Alt+F</code></td><td>全屏截图</td></tr><tr><td><code>Esc</code></td><td>取消/关闭</td></tr><tr><td><code>Enter</code></td><td>确认选区</td></tr></tbody></table><h3 id="编辑相关" tabindex="-1">编辑相关 <a class="header-anchor" href="#编辑相关" aria-label="Permalink to &quot;编辑相关&quot;">​</a></h3><table tabindex="0"><thead><tr><th>快捷键</th><th>功能</th></tr></thead><tbody><tr><td><code>Ctrl+Z</code></td><td>撤销</td></tr><tr><td><code>Ctrl+Y</code></td><td>重做</td></tr><tr><td><code>Delete</code></td><td>删除选中标注</td></tr><tr><td><code>Ctrl+S</code></td><td>保存</td></tr><tr><td><code>Ctrl+C</code></td><td>复制</td></tr></tbody></table><h3 id="选区调整" tabindex="-1">选区调整 <a class="header-anchor" href="#选区调整" aria-label="Permalink to &quot;选区调整&quot;">​</a></h3><table tabindex="0"><thead><tr><th>快捷键</th><th>功能</th></tr></thead><tbody><tr><td><code>方向键</code></td><td>微调选区（1px）</td></tr><tr><td><code>Shift+方向键</code></td><td>微调选区（10px）</td></tr></tbody></table><hr><h2 id="🎯-实用技巧" tabindex="-1">🎯 实用技巧 <a class="header-anchor" href="#🎯-实用技巧" aria-label="Permalink to &quot;🎯 实用技巧&quot;">​</a></h2><h3 id="技巧-1-快速复制" tabindex="-1">技巧 1：快速复制 <a class="header-anchor" href="#技巧-1-快速复制" aria-label="Permalink to &quot;技巧 1：快速复制&quot;">​</a></h3><p>双击选区可以快速复制并退出，无需标注。</p><h3 id="技巧-2-精确选择" tabindex="-1">技巧 2：精确选择 <a class="header-anchor" href="#技巧-2-精确选择" aria-label="Permalink to &quot;技巧 2：精确选择&quot;">​</a></h3><p>使用放大镜（自动显示）和方向键可以精确选择区域。</p><h3 id="技巧-3-窗口截图" tabindex="-1">技巧 3：窗口截图 <a class="header-anchor" href="#技巧-3-窗口截图" aria-label="Permalink to &quot;技巧 3：窗口截图&quot;">​</a></h3><p>移动鼠标到窗口上，窗口会自动高亮，点击即可截取该窗口。</p><h3 id="技巧-4-自动保存" tabindex="-1">技巧 4：自动保存 <a class="header-anchor" href="#技巧-4-自动保存" aria-label="Permalink to &quot;技巧 4：自动保存&quot;">​</a></h3><p>在设置中启用自动保存，截图后自动保存到指定目录，无需手动保存。</p><h3 id="技巧-5-取色器" tabindex="-1">技巧 5：取色器 <a class="header-anchor" href="#技巧-5-取色器" aria-label="Permalink to &quot;技巧 5：取色器&quot;">​</a></h3><p>按 <code>R</code> 键进入取色模式，点击屏幕上的颜色即可拾取。</p><hr><h2 id="⚙️-基本设置" tabindex="-1">⚙️ 基本设置 <a class="header-anchor" href="#⚙️-基本设置" aria-label="Permalink to &quot;⚙️ 基本设置&quot;">​</a></h2><h3 id="打开设置" tabindex="-1">打开设置 <a class="header-anchor" href="#打开设置" aria-label="Permalink to &quot;打开设置&quot;">​</a></h3><p>右键点击托盘图标，选择&quot;设置&quot;。</p><h3 id="推荐设置" tabindex="-1">推荐设置 <a class="header-anchor" href="#推荐设置" aria-label="Permalink to &quot;推荐设置&quot;">​</a></h3><p><strong>启动模式</strong>：</p><ul><li>托盘模式：启动后最小化到托盘（推荐）</li><li>截图模式：启动后立即截图</li><li>隐藏模式：启动后完全隐藏</li></ul><p><strong>开机自启</strong>：</p><ul><li>勾选后，开机自动启动 SnipX</li></ul><p><strong>默认格式</strong>：</p><ul><li>PNG：无损压缩，文件较大（推荐）</li><li>JPG：可调质量，文件较小</li><li>BMP：无压缩，文件最大</li></ul><p><strong>保存路径</strong>：</p><ul><li>设置默认保存路径，方便管理截图</li></ul><hr><h2 id="🆘-常见问题" tabindex="-1">🆘 常见问题 <a class="header-anchor" href="#🆘-常见问题" aria-label="Permalink to &quot;🆘 常见问题&quot;">​</a></h2><h3 id="q1-热键不生效" tabindex="-1">Q1: 热键不生效？ <a class="header-anchor" href="#q1-热键不生效" aria-label="Permalink to &quot;Q1: 热键不生效？&quot;">​</a></h3><p><strong>A</strong>: 检查是否有其他程序占用了热键。可以在设置中更改热键。</p><h3 id="q2-截图后黑屏" tabindex="-1">Q2: 截图后黑屏？ <a class="header-anchor" href="#q2-截图后黑屏" aria-label="Permalink to &quot;Q2: 截图后黑屏？&quot;">​</a></h3><p><strong>A</strong>: 可能是显卡驱动问题。尝试更新显卡驱动或使用兼容模式。</p><h3 id="q3-无法保存截图" tabindex="-1">Q3: 无法保存截图？ <a class="header-anchor" href="#q3-无法保存截图" aria-label="Permalink to &quot;Q3: 无法保存截图？&quot;">​</a></h3><p><strong>A</strong>: 检查保存路径是否有写入权限。</p><h3 id="q4-托盘图标不显示" tabindex="-1">Q4: 托盘图标不显示？ <a class="header-anchor" href="#q4-托盘图标不显示" aria-label="Permalink to &quot;Q4: 托盘图标不显示？&quot;">​</a></h3><p><strong>A</strong>: 在设置中勾选&quot;显示托盘图标&quot;。</p><h3 id="q5-如何卸载" tabindex="-1">Q5: 如何卸载？ <a class="header-anchor" href="#q5-如何卸载" aria-label="Permalink to &quot;Q5: 如何卸载？&quot;">​</a></h3><p><strong>A</strong>:</p><ul><li>单文件版本：直接删除 <code>SnipX.exe</code> 和配置文件</li><li>安装版本：使用&quot;添加或删除程序&quot;卸载</li></ul><hr><h2 id="📚-下一步" tabindex="-1">📚 下一步 <a class="header-anchor" href="#📚-下一步" aria-label="Permalink to &quot;📚 下一步&quot;">​</a></h2><ul><li>📖 查看 <a href="/SnipX/features.html">功能特性</a> 了解截图、标注、取色、贴图和录屏能力</li><li>⌨️ 查看 <a href="/SnipX/guide/shortcuts.html">快捷键</a> 了解所有快捷键</li><li>💾 查看 <a href="/SnipX/download.html">下载页面</a> 获取最新版本</li></ul><hr><h2 id="💬-获取帮助" tabindex="-1">💬 获取帮助 <a class="header-anchor" href="#💬-获取帮助" aria-label="Permalink to &quot;💬 获取帮助&quot;">​</a></h2><p>如果遇到问题：</p><ul><li>📖 查看 <a href="https://github.com/vogadero/SnipX/blob/main/USER_MANUAL.md" target="_blank" rel="noreferrer">用户手册</a></li><li>🐛 <a href="https://github.com/vogadero/SnipX/issues" target="_blank" rel="noreferrer">报告问题</a></li><li>💬 <a href="https://github.com/vogadero/SnipX/discussions" target="_blank" rel="noreferrer">讨论交流</a></li></ul><hr><p><strong>恭喜！你已经学会了 SnipX 的基本使用。</strong> 🎉</p><p>现在可以开始使用 SnipX 进行截图了！</p>',103)])])}const b=t(i,[["render",o]]);export{p as __pageData,b as default};
